-- Plumbing / home-services marketplace schema
-- PostgreSQL 14+ recommended
-- Store image/video files in object storage (e.g. S3-compatible storage), not in PostgreSQL.
-- Store only file URLs and metadata in the database.
-- Password hashes must be generated by Node.js using Argon2id or bcrypt.

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- 1. USERS AND ROLES ---------------------------------------------------------
CREATE TABLE users (
    user_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    full_name VARCHAR(120) NOT NULL CHECK (length(trim(full_name)) >= 2),
    phone_number VARCHAR(24) NOT NULL UNIQUE CHECK (length(trim(phone_number)) >= 7),
    email VARCHAR(254) UNIQUE,
    password_hash TEXT NOT NULL,
    account_status VARCHAR(20) NOT NULL DEFAULT 'Active'
        CHECK (account_status IN ('Active', 'Suspended', 'Pending_Verification', 'Deleted')),
    phone_verified BOOLEAN NOT NULL DEFAULT FALSE,
    email_verified BOOLEAN NOT NULL DEFAULT FALSE,
    last_login_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- A user may have more than one role, e.g. Customer and Master.
CREATE TABLE user_roles (
    user_id UUID NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    role VARCHAR(20) NOT NULL CHECK (role IN ('Customer', 'Master', 'Admin', 'SuperAdmin')),
    assigned_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id, role)
);

CREATE TABLE customer_profiles (
    user_id UUID PRIMARY KEY REFERENCES users(user_id) ON DELETE CASCADE,
    preferred_contact_method VARCHAR(20) NOT NULL DEFAULT 'Platform_Message'
        CHECK (preferred_contact_method IN ('Platform_Message', 'Phone', 'Email')),
    marketing_opt_in BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 2. CATEGORIES AND MASTER PROFILES -----------------------------------------
CREATE TABLE service_categories (
    category_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    parent_category_id BIGINT REFERENCES service_categories(category_id) ON DELETE RESTRICT,
    category_name VARCHAR(100) NOT NULL UNIQUE,
    description TEXT,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE master_profiles (
    user_id UUID PRIMARY KEY REFERENCES users(user_id) ON DELETE CASCADE,
    business_name VARCHAR(160),
    bio TEXT,
    years_experience SMALLINT NOT NULL DEFAULT 0 CHECK (years_experience BETWEEN 0 AND 70),
    verification_status VARCHAR(20) NOT NULL DEFAULT 'Unverified'
        CHECK (verification_status IN ('Unverified', 'Pending', 'Verified', 'Rejected')),
    verification_notes TEXT,
    profile_score NUMERIC(5,2) NOT NULL DEFAULT 0 CHECK (profile_score BETWEEN 0 AND 100),
    is_available BOOLEAN NOT NULL DEFAULT TRUE,
    accepts_emergency_jobs BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE skills (
    skill_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    category_id BIGINT REFERENCES service_categories(category_id) ON DELETE RESTRICT,
    skill_name VARCHAR(120) NOT NULL,
    description TEXT,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    UNIQUE (category_id, skill_name)
);

CREATE TABLE master_skills (
    master_id UUID NOT NULL REFERENCES master_profiles(user_id) ON DELETE CASCADE,
    skill_id BIGINT NOT NULL REFERENCES skills(skill_id) ON DELETE RESTRICT,
    skill_level VARCHAR(20) NOT NULL DEFAULT 'Intermediate'
        CHECK (skill_level IN ('Beginner', 'Intermediate', 'Advanced', 'Expert')),
    years_practiced NUMERIC(4,1) CHECK (years_practiced BETWEEN 0 AND 70),
    PRIMARY KEY (master_id, skill_id)
);

CREATE TABLE master_education (
    education_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    master_id UUID NOT NULL REFERENCES master_profiles(user_id) ON DELETE CASCADE,
    institution_name VARCHAR(200) NOT NULL,
    qualification VARCHAR(200) NOT NULL,
    field_of_study VARCHAR(150),
    year_completed SMALLINT CHECK (year_completed BETWEEN 1950 AND 2100),
    proof_url TEXT,
    verification_status VARCHAR(20) NOT NULL DEFAULT 'Unverified'
        CHECK (verification_status IN ('Unverified', 'Pending', 'Verified', 'Rejected')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE master_certificates (
    certificate_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    master_id UUID NOT NULL REFERENCES master_profiles(user_id) ON DELETE CASCADE,
    certificate_name VARCHAR(200) NOT NULL,
    issuer VARCHAR(200),
    certificate_number VARCHAR(100),
    issued_on DATE,
    expires_on DATE,
    proof_url TEXT,
    verification_status VARCHAR(20) NOT NULL DEFAULT 'Unverified'
        CHECK (verification_status IN ('Unverified', 'Pending', 'Verified', 'Rejected', 'Expired')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (expires_on IS NULL OR issued_on IS NULL OR expires_on >= issued_on)
);

CREATE TABLE master_service_areas (
    service_area_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    master_id UUID NOT NULL REFERENCES master_profiles(user_id) ON DELETE CASCADE,
    city VARCHAR(100) NOT NULL,
    district VARCHAR(100),
    radius_km SMALLINT CHECK (radius_km BETWEEN 1 AND 300),
    travel_fee NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK (travel_fee >= 0),
    UNIQUE (master_id, city, district)
);

CREATE TABLE master_portfolio (
    portfolio_item_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    master_id UUID NOT NULL REFERENCES master_profiles(user_id) ON DELETE CASCADE,
    title VARCHAR(180) NOT NULL,
    description TEXT,
    media_url TEXT NOT NULL,
    media_type VARCHAR(20) NOT NULL DEFAULT 'Image'
        CHECK (media_type IN ('Image', 'Video', 'Document')),
    completed_year SMALLINT CHECK (completed_year BETWEEN 1950 AND 2100),
    display_order INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 3. CUSTOMER LISTINGS -------------------------------------------------------
CREATE TABLE listings (
    listing_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    customer_id UUID NOT NULL REFERENCES customer_profiles(user_id) ON DELETE RESTRICT,
    category_id BIGINT NOT NULL REFERENCES service_categories(category_id) ON DELETE RESTRICT,
    title VARCHAR(200) NOT NULL CHECK (length(trim(title)) >= 5),
    description TEXT NOT NULL CHECK (length(trim(description)) >= 10),
    problem_details JSONB NOT NULL DEFAULT '{}'::jsonb,
    urgency VARCHAR(20) NOT NULL DEFAULT 'Normal'
        CHECK (urgency IN ('Low', 'Normal', 'Urgent', 'Emergency')),
    city VARCHAR(100) NOT NULL,
    district VARCHAR(100) NOT NULL,
    public_location_description VARCHAR(250),
    full_address TEXT NOT NULL,
    latitude NUMERIC(9,6) CHECK (latitude BETWEEN -90 AND 90),
    longitude NUMERIC(9,6) CHECK (longitude BETWEEN -180 AND 180),
    address_visibility VARCHAR(25) NOT NULL DEFAULT 'After_Acceptance'
        CHECK (address_visibility IN ('Approximate_Only', 'After_Acceptance')),
    budget_min NUMERIC(12,2) CHECK (budget_min IS NULL OR budget_min >= 0),
    budget_max NUMERIC(12,2) CHECK (budget_max IS NULL OR budget_max >= 0),
    budget_type VARCHAR(20) NOT NULL DEFAULT 'Negotiable'
        CHECK (budget_type IN ('Fixed', 'Range', 'Negotiable', 'Unknown')),
    preferred_at_from TIMESTAMPTZ,
    preferred_at_to TIMESTAMPTZ,
    status VARCHAR(20) NOT NULL DEFAULT 'Draft'
        CHECK (status IN ('Draft', 'Published', 'In_Progress', 'Completed', 'Cancelled', 'Expired', 'Hidden')),
    published_at TIMESTAMPTZ,
    expires_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_listing_budget_order CHECK (budget_min IS NULL OR budget_max IS NULL OR budget_max >= budget_min),
    CONSTRAINT chk_listing_preferred_window CHECK (preferred_at_from IS NULL OR preferred_at_to IS NULL OR preferred_at_to >= preferred_at_from),
    CONSTRAINT chk_listing_expiry CHECK (expires_at IS NULL OR expires_at >= created_at),
    UNIQUE (listing_id, customer_id)
);

CREATE TABLE listing_attachments (
    attachment_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    listing_id UUID NOT NULL REFERENCES listings(listing_id) ON DELETE CASCADE,
    uploaded_by UUID NOT NULL REFERENCES users(user_id) ON DELETE RESTRICT,
    file_url TEXT NOT NULL,
    original_file_name VARCHAR(255),
    mime_type VARCHAR(100) NOT NULL,
    file_size_bytes BIGINT NOT NULL CHECK (file_size_bytes > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (mime_type LIKE 'image/%' OR mime_type LIKE 'video/%' OR mime_type = 'application/pdf')
);

-- 4. MASTER OFFERS / PRICE QUOTES -------------------------------------------
CREATE TABLE master_offers (
    offer_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    listing_id UUID NOT NULL REFERENCES listings(listing_id) ON DELETE RESTRICT,
    master_id UUID NOT NULL REFERENCES master_profiles(user_id) ON DELETE RESTRICT,
    message TEXT NOT NULL CHECK (length(trim(message)) >= 5),
    proposed_total NUMERIC(12,2) NOT NULL CHECK (proposed_total >= 0),
    currency CHAR(3) NOT NULL DEFAULT 'AZN' CHECK (currency = upper(currency)),
    price_type VARCHAR(20) NOT NULL DEFAULT 'Estimated'
        CHECK (price_type IN ('Fixed', 'Estimated', 'Hourly')),
    labor_cost NUMERIC(12,2) CHECK (labor_cost IS NULL OR labor_cost >= 0),
    materials_cost NUMERIC(12,2) CHECK (materials_cost IS NULL OR materials_cost >= 0),
    travel_cost NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (travel_cost >= 0),
    other_cost NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (other_cost >= 0),
    materials_included BOOLEAN NOT NULL DEFAULT FALSE,
    possible_extra_cost BOOLEAN NOT NULL DEFAULT FALSE,
    extra_cost_limit NUMERIC(12,2) CHECK (extra_cost_limit IS NULL OR extra_cost_limit >= 0),
    extra_cost_conditions TEXT,
    estimated_duration_value NUMERIC(8,2) NOT NULL CHECK (estimated_duration_value > 0),
    estimated_duration_unit VARCHAR(10) NOT NULL
        CHECK (estimated_duration_unit IN ('Minutes', 'Hours', 'Days')),
    available_from TIMESTAMPTZ,
    available_to TIMESTAMPTZ,
    warranty_days INTEGER NOT NULL DEFAULT 0 CHECK (warranty_days BETWEEN 0 AND 3650),
    status VARCHAR(20) NOT NULL DEFAULT 'Pending'
        CHECK (status IN ('Pending', 'Shortlisted', 'Accepted', 'Rejected', 'Withdrawn', 'Expired')),
    valid_until TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (available_from IS NULL OR available_to IS NULL OR available_to >= available_from),
    CHECK (NOT possible_extra_cost OR extra_cost_conditions IS NOT NULL),
    UNIQUE (listing_id, master_id),
    UNIQUE (offer_id, listing_id, master_id),
    UNIQUE (offer_id, listing_id)
);

-- 5. ACCEPTED JOB, PAYMENTS AND REVIEWS -------------------------------------
CREATE TABLE jobs (
    job_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    listing_id UUID NOT NULL UNIQUE,
    offer_id UUID NOT NULL UNIQUE,
    customer_id UUID NOT NULL,
    master_id UUID NOT NULL,
    agreed_price NUMERIC(12,2) NOT NULL CHECK (agreed_price >= 0),
    currency CHAR(3) NOT NULL DEFAULT 'AZN',
    status VARCHAR(25) NOT NULL DEFAULT 'Agreed'
        CHECK (status IN ('Agreed', 'Scheduled', 'In_Progress', 'Completed', 'Cancelled', 'Disputed')),
    scheduled_at TIMESTAMPTZ,
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    cancelled_by UUID REFERENCES users(user_id) ON DELETE RESTRICT,
    cancellation_reason TEXT,
    customer_confirmed_completion BOOLEAN NOT NULL DEFAULT FALSE,
    master_confirmed_completion BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (listing_id, customer_id) REFERENCES listings(listing_id, customer_id) ON DELETE RESTRICT,
    FOREIGN KEY (offer_id, listing_id, master_id) REFERENCES master_offers(offer_id, listing_id, master_id) ON DELETE RESTRICT,
    UNIQUE (job_id, customer_id, master_id),
    CHECK (completed_at IS NULL OR started_at IS NULL OR completed_at >= started_at),
    CHECK ((status <> 'Cancelled') OR cancellation_reason IS NOT NULL)
);

CREATE TABLE payments (
    payment_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    job_id UUID NOT NULL REFERENCES jobs(job_id) ON DELETE RESTRICT,
    initiated_by UUID NOT NULL REFERENCES users(user_id) ON DELETE RESTRICT,
    provider VARCHAR(50),
    provider_transaction_id VARCHAR(200) UNIQUE,
    amount NUMERIC(12,2) NOT NULL CHECK (amount >= 0),
    platform_fee NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (platform_fee >= 0),
    refunded_amount NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (refunded_amount >= 0 AND refunded_amount <= amount),
    currency CHAR(3) NOT NULL DEFAULT 'AZN',
    payment_method VARCHAR(30) CHECK (payment_method IN ('Card', 'Cash', 'Bank_Transfer', 'Wallet', 'Other')),
    status VARCHAR(20) NOT NULL DEFAULT 'Pending'
        CHECK (status IN ('Pending', 'Authorized', 'Paid', 'Failed', 'Partially_Refunded', 'Refunded', 'Cancelled')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE reviews (
    review_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    job_id UUID NOT NULL UNIQUE,
    customer_id UUID NOT NULL,
    master_id UUID NOT NULL,
    rating SMALLINT NOT NULL CHECK (rating BETWEEN 1 AND 5),
    review_text TEXT,
    professionalism_rating SMALLINT CHECK (professionalism_rating BETWEEN 1 AND 5),
    quality_rating SMALLINT CHECK (quality_rating BETWEEN 1 AND 5),
    punctuality_rating SMALLINT CHECK (punctuality_rating BETWEEN 1 AND 5),
    response_from_master TEXT,
    is_hidden BOOLEAN NOT NULL DEFAULT FALSE,
    moderated_by UUID REFERENCES users(user_id) ON DELETE RESTRICT,
    moderated_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (job_id, customer_id, master_id) REFERENCES jobs(job_id, customer_id, master_id) ON DELETE RESTRICT
);

-- 6. MESSAGES, DISPUTES AND REPORTS -----------------------------------------
CREATE TABLE messages (
    message_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    listing_id UUID NOT NULL REFERENCES listings(listing_id) ON DELETE RESTRICT,
    offer_id UUID,
    sender_id UUID NOT NULL REFERENCES users(user_id) ON DELETE RESTRICT,
    receiver_id UUID NOT NULL REFERENCES users(user_id) ON DELETE RESTRICT,
    message_text TEXT,
    attachment_urls JSONB NOT NULL DEFAULT '[]'::jsonb,
    sent_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    read_at TIMESTAMPTZ,
    is_deleted_for_sender BOOLEAN NOT NULL DEFAULT FALSE,
    is_deleted_for_receiver BOOLEAN NOT NULL DEFAULT FALSE,
    FOREIGN KEY (offer_id, listing_id) REFERENCES master_offers(offer_id, listing_id) ON DELETE RESTRICT,
    CHECK (sender_id <> receiver_id),
    CHECK (message_text IS NOT NULL OR attachment_urls <> '[]'::jsonb)
);

CREATE TABLE disputes (
    dispute_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    job_id UUID NOT NULL,
    customer_id UUID NOT NULL,
    master_id UUID NOT NULL,
    opened_by UUID NOT NULL REFERENCES users(user_id) ON DELETE RESTRICT,
    reason VARCHAR(60) NOT NULL
        CHECK (reason IN ('Poor_Quality', 'Price_Disagreement', 'No_Show', 'Damage', 'Extra_Cost', 'Safety', 'Other')),
    description TEXT NOT NULL,
    evidence_urls JSONB NOT NULL DEFAULT '[]'::jsonb,
    status VARCHAR(20) NOT NULL DEFAULT 'Open'
        CHECK (status IN ('Open', 'Under_Review', 'Resolved', 'Rejected', 'Escalated')),
    resolution TEXT,
    resolved_by UUID REFERENCES users(user_id) ON DELETE RESTRICT,
    resolved_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (job_id, customer_id, master_id) REFERENCES jobs(job_id, customer_id, master_id) ON DELETE RESTRICT
);

CREATE TABLE reports (
    report_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    reported_by UUID NOT NULL REFERENCES users(user_id) ON DELETE RESTRICT,
    reported_user_id UUID REFERENCES users(user_id) ON DELETE RESTRICT,
    listing_id UUID REFERENCES listings(listing_id) ON DELETE RESTRICT,
    offer_id UUID REFERENCES master_offers(offer_id) ON DELETE RESTRICT,
    message_id UUID REFERENCES messages(message_id) ON DELETE RESTRICT,
    reason VARCHAR(60) NOT NULL
        CHECK (reason IN ('Spam', 'Fraud', 'Abuse', 'Fake_Profile', 'Unsafe_Behavior', 'Incorrect_Listing', 'Other')),
    description TEXT,
    status VARCHAR(20) NOT NULL DEFAULT 'Open'
        CHECK (status IN ('Open', 'Under_Review', 'Action_Taken', 'Dismissed', 'Closed')),
    admin_notes TEXT,
    handled_by UUID REFERENCES users(user_id) ON DELETE RESTRICT,
    handled_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (reported_user_id IS NOT NULL OR listing_id IS NOT NULL OR offer_id IS NOT NULL OR message_id IS NOT NULL)
);

-- 7. NOTIFICATIONS AND AUDIT LOGS -------------------------------------------
CREATE TABLE notifications (
    notification_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    notification_type VARCHAR(50) NOT NULL,
    title VARCHAR(180) NOT NULL,
    body TEXT NOT NULL,
    payload JSONB NOT NULL DEFAULT '{}'::jsonb,
    read_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Node.js should write an audit row for admin moderation and other important actions.
-- Never copy passwords, password hashes, tokens, full card data, or unnecessary PII into old_data/new_data.
CREATE TABLE audit_logs (
    audit_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    actor_user_id UUID REFERENCES users(user_id) ON DELETE SET NULL,
    action VARCHAR(80) NOT NULL,
    entity_type VARCHAR(80) NOT NULL,
    entity_id UUID,
    old_data JSONB,
    new_data JSONB,
    ip_address INET,
    user_agent TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 8. OPTIONAL ML OUTPUT STORAGE ---------------------------------------------
-- Python may save predictions/scores here; predictions must not replace source-of-truth records.
CREATE TABLE ml_predictions (
    prediction_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    task_name VARCHAR(100) NOT NULL,
    entity_type VARCHAR(40) NOT NULL CHECK (entity_type IN ('Listing', 'Master', 'Offer', 'User')),
    entity_id UUID NOT NULL,
    model_name VARCHAR(120) NOT NULL,
    model_version VARCHAR(80) NOT NULL,
    prediction JSONB NOT NULL,
    score NUMERIC(12,6),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 9. INDEXES -----------------------------------------------------------------
CREATE INDEX idx_users_status ON users(account_status);
CREATE INDEX idx_user_roles_role ON user_roles(role, user_id);
CREATE INDEX idx_master_profiles_available ON master_profiles(is_available, verification_status);
CREATE INDEX idx_master_service_areas_location ON master_service_areas(city, district);
CREATE INDEX idx_master_skills_skill ON master_skills(skill_id, master_id);
CREATE INDEX idx_listings_status_created ON listings(status, created_at DESC);
CREATE INDEX idx_listings_area_status ON listings(city, district, status);
CREATE INDEX idx_listings_category_status ON listings(category_id, status);
CREATE INDEX idx_listings_customer ON listings(customer_id, created_at DESC);
CREATE INDEX idx_offers_listing_status ON master_offers(listing_id, status, created_at DESC);
CREATE UNIQUE INDEX uq_one_accepted_offer_per_listing ON master_offers(listing_id) WHERE status = 'Accepted';
CREATE INDEX idx_offers_master ON master_offers(master_id, created_at DESC);
CREATE INDEX idx_jobs_master_status ON jobs(master_id, status, created_at DESC);
CREATE INDEX idx_jobs_customer_status ON jobs(customer_id, status, created_at DESC);
CREATE INDEX idx_messages_listing_sent ON messages(listing_id, sent_at);
CREATE INDEX idx_messages_receiver_unread ON messages(receiver_id, sent_at DESC) WHERE read_at IS NULL;
CREATE INDEX idx_reviews_master ON reviews(master_id, created_at DESC) WHERE is_hidden = FALSE;
CREATE INDEX idx_disputes_status ON disputes(status, created_at DESC);
CREATE INDEX idx_reports_status ON reports(status, created_at DESC);
CREATE INDEX idx_notifications_user_unread ON notifications(user_id, created_at DESC) WHERE read_at IS NULL;
CREATE INDEX idx_audit_logs_entity ON audit_logs(entity_type, entity_id, created_at DESC);
CREATE INDEX idx_audit_logs_actor ON audit_logs(actor_user_id, created_at DESC);
CREATE INDEX idx_ml_predictions_entity ON ml_predictions(entity_type, entity_id, task_name, created_at DESC);

-- 10. UPDATED_AT TRIGGER -----------------------------------------------------
CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_users_updated_at BEFORE UPDATE ON users
FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_master_profiles_updated_at BEFORE UPDATE ON master_profiles
FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_listings_updated_at BEFORE UPDATE ON listings
FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_master_offers_updated_at BEFORE UPDATE ON master_offers
FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_jobs_updated_at BEFORE UPDATE ON jobs
FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_payments_updated_at BEFORE UPDATE ON payments
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- 11. REPORTING VIEW ---------------------------------------------------------
CREATE OR REPLACE VIEW master_public_stats AS
WITH rating_stats AS (
    SELECT master_id,
           ROUND(AVG(rating)::numeric, 2) AS average_rating,
           COUNT(*)::integer AS rating_count
    FROM reviews
    WHERE is_hidden = FALSE
    GROUP BY master_id
), job_stats AS (
    SELECT master_id,
           COUNT(*) FILTER (WHERE status = 'Completed')::integer AS completed_jobs_count,
           COUNT(*) FILTER (WHERE status = 'Cancelled')::integer AS cancelled_jobs_count
    FROM jobs
    GROUP BY master_id
)
SELECT mp.user_id AS master_id,
       mp.business_name,
       mp.years_experience,
       mp.verification_status,
       mp.profile_score,
       mp.is_available,
       COALESCE(rs.average_rating, 0)::numeric(3,2) AS average_rating,
       COALESCE(rs.rating_count, 0) AS rating_count,
       COALESCE(js.completed_jobs_count, 0) AS completed_jobs_count,
       COALESCE(js.cancelled_jobs_count, 0) AS cancelled_jobs_count
FROM master_profiles mp
LEFT JOIN rating_stats rs ON rs.master_id = mp.user_id
LEFT JOIN job_stats js ON js.master_id = mp.user_id;

